function App() {
  const [selectedNum, setSelectedNum] = useState(100)
  const time = useTime()  // 1초마다 업데이트

  // selectedNum까지 모든 소수 계산
  const allPrimes = []
  for (let counter = 2; counter < selectedNum; counter++) {
    if (isPrime(counter)) allPrimes.push(counter)
  }

  return (
    <>
      <p>{format(time, 'hh:mm:ss a')}</p>
      <input value={selectedNum} onChange={...} />
      <p>{allPrimes.join(', ')}</p>
    </>
  )
}

