function AuthProvider({ user, status, children }) {
  // Consumer들이 불필요하게 리렌더링 안 하도록
  const value = useMemo(() => ({
    user,
    status,
  }), [user, status])

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  )
}

